from common import *
S=[
section('5.1','Per cent and equivalent representations','Per cent',
 'Read “per cent” as “out of one hundred”, then connect fractions, decimals and percentages.',
 ['A percentage is a ratio with denominator 100. 37% means 37/100 = 0.37. A percentage can exceed 100 when the amount is more than the reference whole.',
  'To write a fraction as a percentage, find an equivalent fraction out of 100 or multiply by 100%. To write a percentage as a fraction, put it over 100 and simplify.'],
 ex('Connect 3/5, 0.6 and 60%','Scale the fraction to hundredths.', ['3/5 = 60/100.','60/100 = 0.60 = 60%.'], 'All three name the same proportion.'),
 'Percentages compare to a stated whole. 50% of different totals need not be equal amounts.',[
 q('5.1.1','fluency','Write 37%, 5% and 125% as decimals.','0.37, 0.05 and 1.25.','Divide by 100.',v('[37/100,5/100,125/100]',[0.37,0.05,1.25])),
 q('5.1.2','fluency','Write 3/5, 7/20 and 1/8 as percentages.','60%, 35% and 12.5%.','Multiply each fraction by 100%.',v('[float(F(3,5)*100),float(F(7,20)*100),float(F(1,8)*100)]',[60,35,12.5])),
 q('5.1.3','fluency','Write 24% and 150% as fractions in simplest form.','6/25 and 3/2.','24/100 and 150/100, then simplify.',v('[F(24,100),F(150,100)]',['6/25','3/2'])),
 q('5.1.4','reasoning','A student says 0.5% = 0.5. Correct the statement.','0.5% = 0.005. 0.5 = 50%.','Per cent means divide by 100.',v('0.5/100',0.005)),
 q('5.1.5','application','In a group of 40, 18 choose football. What percentage is that?','45%.','18/40 × 100 = 45.',v('18/40*100',45)),
 q('5.1.6','challenge','Can a quantity be 120% of a reference amount? Give an example.','Yes. If the reference is 50, then 60 is 120% of it.','Percentages above 100 represent more than the reference whole.',v('60/50*100',120))],{'kind':'percent_grid','shaded':37,'caption':'37 of 100 equal squares: 37/100 = 0.37 = 37%.'}),
section('5.2','Finding a percentage of a quantity','Percentage of',
 'Translate “of” into multiplication and identify the reference amount first.',
 ['p% of A means p/100 × A. Useful benchmarks are 10% (divide by 10), 1% (divide by 100), 50% (halve) and 25% (quarter). Build other percentages from these.',
  'For 15% of 240, find 10% = 24 and 5% = 12, then add: 36. Or use the multiplier 0.15 × 240 = 36.'],
 ex('Find 12.5% of 320','Use a fraction benchmark.', ['12.5% = 1/8.','320 ÷ 8 = 40.'], '40.'),
 'A percentage is not an amount until its whole is known. 20% of 50 and 20% of 200 are different.',[
 q('5.2.1','fluency','Find 10%, 25% and 15% of 240.','24, 60 and 36.','Use a tenth, a quarter, and a tenth plus half a tenth.',v('[240*0.1,240*0.25,240*0.15]',[24,60,36])),
 q('5.2.2','fluency','Find 12.5% of 320 and 1% of 750.','40 and 7.5.','12.5% = 1/8; 1% means divide by 100.',v('[320/8,750/100]',[40,7.5])),
 q('5.2.3','reasoning','Explain two ways to find 35% of 80.','28. Use 0.35×80, or 25% (20) + 10% (8).','Both methods use the same reference whole.',v('[0.35*80,80/4+80/10]',[28,28])),
 q('5.2.4','application','A £60 jacket is reduced by 20%. Find the reduction and sale price.','Reduction £12; sale price £48.','20% of 60 is 12; subtract from 60.',v('[60*0.2,60*0.8]',[12,48])),
 q('5.2.5','reasoning','Is 30% of 50 equal to 50% of 30? Explain.','Yes, both are 15. Multiplication can be done in either order.','30/100×50 = 50/100×30.',v('[0.3*50,0.5*30]',[15,15])),
 q('5.2.6','challenge','15% of a number is 27. Find the number.','180.','27 ÷ 0.15 = 180.',v('27/0.15',180))]),
section('5.3','Percentage increase and decrease','Change',
 'Find the change from the original amount, or use a single multiplier.',
 ['An increase of p% uses multiplier 1 + p/100; a decrease uses 1 − p/100. The original amount is the reference unless the question says otherwise.',
  'Percentage change = change/original × 100%. A 20% increase followed by a 20% decrease uses 1.2 × 0.8 = 0.96, ending at 96% of the start.'],
 ex('£250 with 20% off, then 10% off','Apply each multiplier to the current price.', ['250 × 0.8 = 200.','200 × 0.9 = 180.','A single 30% discount would give 175.'], '£180; total discount 28%, not 30%.'),
 'The second percentage uses a new base. Do not add successive percentage changes unless they apply to the same unchanged whole.',[
 q('5.3.1','fluency','Increase 80 by 15% and decrease 80 by 15%.','92 and 68.','Use multipliers 1.15 and 0.85.',v('[80*1.15,80*0.85]',[92,68])),
 q('5.3.2','fluency','A price rises from 50 to 60. Find the percentage increase.','20%.','Change 10 divided by original 50, times 100.',v('(60-50)/50*100',20)),
 q('5.3.3','application','Apply 20% off then 10% off to £250. Compare with 30% off.','£180 versus £175; the single 30% offer is £5 cheaper.','250×0.8×0.9 = 180; 250×0.7 = 175.',v('[250*0.8*0.9,250*0.7,250*0.7-250*0.8*0.9]',[180,175,-5])),
 q('5.3.4','reasoning','Increase £100 by 20%, then decrease the result by 20%. Explain the final amount.','£96. The 20% decrease is £24, larger than the original £20 increase.','The base changed from 100 to 120.',v('100*1.2*0.8',96)),
 q('5.3.5','reasoning','Does reversing 10% off and 20% off change the final price?','No. 0.9×0.8 = 0.8×0.9 = 0.72.','Multiplication is commutative.',v('[0.9*0.8,0.8*0.9]',[0.72,0.72])),
 q('5.3.6','challenge','A value falls by 20%. What percentage increase restores the original?','25%.','From 80 back to 100, the increase is 20/80 = 25%.',v('(1/0.8-1)*100',25))],{'kind':'multiplier_flow','start':250,'steps':[[0.8,'20% off'],[0.9,'10% off']],'caption':'Each multiplier acts on the current amount: 250 → 200 → 180.'}),
section('5.4','Discounts, taxes, profit and budgets','Money decisions',
 'Separate revenue, costs and profit; apply percentages to the correct line of a budget.',
 ['A discount reduces a marked price. A tax or tip usually increases a stated base. Revenue is money received; cost is money spent; profit is revenue minus all relevant costs.',
  'For a budget, calculate each line, then add. Whole-item purchases may require rounding up. A lower unit price is not automatically a better decision if extra stock cannot be sold.'],
 ex('A market-stall budget','Sell 20 honey jars at £8.10, 36 soaps at £3 and 25 jams at £5.', ['Revenue = 162 + 108 + 125 = £395.','Goods cost = 20×6 + 36×2.50 + 25×3.20 = £290.','Fixed costs = 45 + 18 = £63.'], 'Net profit = 395 − 290 − 63 = £42.'),
 'Gross profit subtracts goods cost only; net profit also subtracts fixed costs. State which profit you mean.',[
 q('5.4.1','fluency','A £9 item has 10% off. A £4 item has 25% off. Find both sale prices.','£8.10 and £3.00.','Use multipliers 0.9 and 0.75.',v('[9*0.9,4*0.75]',[8.1,3])),
 q('5.4.2','application','A meal costs £40 before 10% tax. Find the total.','£44.','Tax £4; total 40×1.1.',v('40*1.1',44)),
 q('5.4.3','application','Revenue is £395, goods cost £290 and fixed costs £63. Find gross and net profit.','Gross £105; net £42.','Gross = 395−290; net = 105−63.',v('[395-290,395-290-63]',[105,42])),
 q('5.4.4','reasoning','A shop buys an item for £6 and sells it for £9. Is the profit 50% of cost or of selling price? Calculate both.','£3 profit: 50% of cost, 33 1/3% of selling price.','The denominator changes the percentage.',v('[3/6*100,float(F(3,9)*100)]',[50,float(F(100,3))])),
 q('5.4.5','application','A group needs 23 jars at £6 each. A supplier offers 30 jars at 10% off the £6 cost. Compare total outlay.','23 jars cost £138; 30 at £5.40 cost £162, £24 more.','The lower unit price requires buying 7 extra jars.',v('[23*6,30*6*0.9,30*6*0.9-23*6]',[138,162,24])),
 q('5.4.6','challenge','Fixed costs of £63 rise by 8%. With revenue £395 and goods cost £290, find the new net profit.','£36.96.','New fixed costs 63×1.08 = £68.04; net = 395−290−68.04.',v('round(395-290-63*1.08,2)',36.96))])
]
ready=[q('R1','ready','Find 10% of 90.','9.','Divide by 10.',v('90/10',9)),q('R2','ready','Write 1/2 as a decimal and percentage.','0.5 and 50%.','Half of 100 is 50.',v('[0.5,50]',[0.5,50])),q('R3','ready','Calculate 0.2×50.','10.','One fifth of 50.',v('0.2*50',10)),q('R4','ready','Find 60−12.','48.','Subtract the reduction.',v('60-12',48)),q('R5','ready','Write 75/100 in simplest form.','3/4.','Divide by 25.',v('F(75,100)','3/4'))]
check=[q('C1','check','Find 15% of 200.','30.','10% is 20; 5% is 10.',v('200*0.15',30)),q('C2','check','Increase 50 by 12%.','56.','50×1.12.',v('50*1.12',56)),q('C3','check','A price falls from 80 to 60. Find the percentage decrease.','25%.','20/80×100.',v('(80-60)/80*100',25)),q('C4','check','Find the single multiplier for 10% off then 20% off.','0.72, equivalent to 28% off.','0.9×0.8.',v('0.9*0.8',0.72))]
explore=dict(title='Do two discounts add up?',instruction='Criterion B. Use multipliers to test a rule, then explain why it holds for every starting price.',intro='Offer A: 20% off, then 10% off. Offer B: 30% off. Test both on £250, £40 and £80.',table={'headers':['Start','A: 20% then 10%','B: 30%'],'rows':[['£250','',''],['£40','',''],['£80','','']]},items=[
q('B1','investigation','Complete the table for £250, £40 and £80.','A: £180, £28.80, £57.60. B: £175, £28, £56.','Use 0.8×0.9 = 0.72 and 0.7.',v('[[round(p*0.72,2),round(p*0.7,2)] for p in [250,40,80]]',[[180,175],[28.8,28],[57.6,56]])),
q('B2','investigation','What single discount is equivalent to 20% then 10%? Does order matter?','28%; order does not matter because 0.8×0.9 = 0.9×0.8.','The product of multipliers is unchanged by order.',v('[round((1-0.8*0.9)*100,8),0.8*0.9==0.9*0.8]',[28,True])),
q('B3','investigation','Find the combined discount for 25% then 20%.','40%.','0.75×0.8 = 0.60 remains.',v('round((1-0.75*0.8)*100,8)',40)),
q('B4','challenge','Is there a distinct unordered pair of whole-number percentage discounts, other than 20% and 10%, giving exactly 28% off? Justify your answer.','Yes: 4% then 25% (or 25% then 4%), since 0.96×0.75 = 0.72. The pair 10% and 20% also works but is excluded by the question.','Solve (100−a)(100−b)=7200; factor pairs in range include 96×75 and 80×90.',v('[(a,b) for a in range(1,100) for b in range(a,100) if (100-a)*(100-b)==7200]',[(4,25),(10,20)])),
q('B5','investigation','Write a rule for successive discounts a% and b%, and explain the base.','Remaining multiplier (1−a/100)(1−b/100); combined discount is 1 minus this product. The second discount uses the reduced price.','Multiplying multipliers tracks the changing base.',v('round((1-(1-0.2)*(1-0.1))*100,8)',28,contains=['reduced']))])
